# Code generated by Claude
"""
Measurement only (David, Part 5 step 3, 2026-10-26): at the chosen spot of a layout, how close each left-arm joint is to its limit at the place's carry stop, at the chosen hand turn theta and at theta = 0.

    MUJOCO_GL=egl python experiments/place_theta_report.py moved|normal

Runs the pipeline's stance selection (src/stance_select.apply_stance_selection with a recording wrapper on the full check), then solves the carry stop (the place's OVER) with the full check's exact-pose IK
at theta (the chosen one) and at theta = 0, from random starts and the best solution is kept (the smallest pose error; at theta = 0 it may be outside the tolerance, that is shown). For each: the position and
rotation error, and per joint the distance to the real joint limit and to the solver's own bound (the limit less the 10 degree margin), radians. Output: docs/reports/logs/place_theta_report_<layout>.json.
"""
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402
from scipy.spatial.transform import Rotation  # noqa: E402

import src.bench_stance as bs  # noqa: E402
from src.arm_kinematics import batch_fk, solve_ik  # noqa: E402
from src.full_check import FullCheck  # noqa: E402
from src.grasp_rules import make_pose_constraint  # noqa: E402
from src.mpvi_postprocess import postprocess  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.stance_select import make_context, select_bench_stance  # noqa: E402
from src.task_config import BENCH_STANCE_CFG, FULLCHECK_CFG, TASK_CFG  # noqa: E402
from src.world_model import StaticTaskSource, WorldModel  # noqa: E402
from stance_select_moved_test import MOVED  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402


class Rec:
    def __init__(self, fc):
        self.fc, self.calls = fc, []

    def check(self, stance, points, *a, **k):
        r = self.fc.check(stance, points, *a, **k)
        self.calls.append((tuple(float(v) for v in stance), points, r))
        return r


def main():
    name = sys.argv[1]
    cfg = {"moved": MOVED, "normal": TASK_CFG}[name]
    say = lambda *a: None
    maps = bs.load_maps("data/reach_map", sides=("left",))
    fc = FullCheck(maps={**bs.load_maps("data/reach_map")}, task_cfg=cfg, say=say)
    ctx = make_context(fc.model, fc.scene_data, maps, cfg, BENCH_STANCE_CFG, chk=fc.chk, say=say)
    world = WorldModel([StaticTaskSource(cfg)])
    world.refresh(0.0)
    rec = Rec(fc)
    sel = select_bench_stance(postprocess(PLAN4, False, say=say), world, cfg, ctx, BENCH_STANCE_CFG, full_check=rec, say=say)
    run = sel["report"]["runs"][0]
    st = run["stance"]
    stance = (float(st["xy"][0]), float(st["xy"][1]), float(st["yaw"]), float(st["q"]))
    theta_chosen = run["place_theta_deg"]
    place = [c for c in rec.calls if abs(c[0][0] - stance[0]) < 1e-9 and abs(c[0][1] - stance[1]) < 1e-9 and abs(c[0][3] - stance[3]) < 1e-9][-1]
    pts, res = place[1], place[2]
    carry = [pt for pt in pts if pt.get("path") == "carry"][0]
    T = fc.to_torso(stance, np.array([carry["p"]], float))[0]
    ids = arm_ids(fc.model, "left")
    jr = fc.model.jnt_range[ids["jnt"]]
    out = {"layout": name, "stance": list(stance), "chosen_theta_deg": theta_chosen, "window": res["place"]["window_deg"], "width_deg": res["place"]["width_deg"], "passing_deg": res["place"]["passing_deg"],
           "windows": res["place"]["windows"], "carry_stop_world": carry["p"], "joint_limits": jr.tolist(), "solver_bounds": [fc.lo.tolist(), fc.hi.tolist()], "turns": {}}
    rng = np.random.default_rng(5)
    for deg in (theta_chosen, 0):
        tp, R = fc._pose_target(stance, carry, T, math.radians(deg))
        Q0 = rng.uniform(fc.lo, fc.hi, (400, 7))
        Q, _, _ = solve_ik(fc.chain, Q0, fc.lo, fc.hi, make_pose_constraint(np.repeat(tp[None, :], len(Q0), axis=0), R), fc.pad, 300, fc.C["ik_damping"], fc.C["ik_max_step"])
        p, Rf = batch_fk(fc.chain, Q, fc.pad)
        err = np.linalg.norm(p - tp, axis=1)
        ang = np.linalg.norm(Rotation.from_matrix(R[None] @ Rf.transpose(0, 2, 1)).as_rotvec(), axis=1)
        j = int(np.argmin(err + 0.2 * ang))
        q = Q[j]
        out["turns"][str(deg)] = {"theta_deg": deg, "pos_err_mm": 1000 * float(err[j]), "rot_err_deg": math.degrees(float(ang[j])), "q": q.round(4).tolist(),
                                  "dist_to_limit_rad": np.minimum(q - jr[:, 0], jr[:, 1] - q).round(4).tolist(), "dist_to_solver_bound_rad": np.minimum(q - fc.lo, fc.hi - q).round(4).tolist(),
                                  "within_tolerance": bool(err[j] <= 0.003 and ang[j] <= math.radians(2.0)), "starts_within_tolerance": int(np.sum((err <= 0.003) & (ang <= math.radians(2.0))))}
        print(deg, {k: v for k, v in out["turns"][str(deg)].items() if k != "q"}, flush=True)
    Path("docs/reports/logs").mkdir(parents=True, exist_ok=True)
    tmp = Path(f"docs/reports/logs/place_theta_report_{name}.json.tmp")
    tmp.write_text(json.dumps(out, indent=1, default=str))
    tmp.replace(Path(f"docs/reports/logs/place_theta_report_{name}.json"))


if __name__ == "__main__":
    main()
